async function scanBundle(input, deliver) {
  let count = 0;
  let line = 1;
  let parts = [];

  try {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });

    async function deliverLine(text) {
      if (text.trim() === "") return true;

      let value;
      try {
        value = JSON.parse(text);
      } catch {
        const error = new Error("Invalid JSON on line " + line);
        error.code = "BAD_LINE";
        error.line = line;
        throw error;
      }

      count++;
      return (await deliver(value, line)) !== false;
    }

    for (;;) {
      const chunk = await input.read();

      if (chunk === null) {
        const tail = decoder.decode();
        if (tail.length > 0) parts.push(tail);

        const text = parts.join("");
        parts = [];
        await deliverLine(text);
        return count;
      }

      let start = 0;

      while (start < chunk.length) {
        const newline = chunk.indexOf(10, start);
        const end = newline === -1 ? chunk.length : newline;
        const fragment = decoder.decode(chunk.subarray(start, end), {
          stream: true
        });

        if (fragment.length > 0) parts.push(fragment);
        if (newline === -1) break;

        const text = parts.join("");
        parts = [];

        if (!(await deliverLine(text))) return count;

        line++;
        start = newline + 1;
      }
    }
  } finally {
    await input.close();
  }
}
